// Generar fecha de hoy en formato YYYY-MM-DD
const now = new Date();
const yyyy = now.getFullYear();
const mm = String(now.getMonth() + 1).padStart(2, '0');
const dd = String(now.getDate()).padStart(2, '0');
const fecha = `${yyyy}-${mm}-${dd}`;

return {
  json: {
    fecha,
    startISO: `${fecha}T00:00:00Z`,
    endISO: `${fecha}T23:59:59Z`,
    fechaED: fecha
  }
};

// Buscar datos del TMS y ED desde los nodos anteriores
let csvData = '';
let excelB64 = null;

// CSV del TMS — viene del input directo
try {
  const tmsItem = $input.first();
  csvData = tmsItem.json.data || tmsItem.json.body || tmsItem.json || '';
  if (typeof csvData !== 'string') csvData = JSON.stringify(csvData);
} catch(e) {
  console.log('Error obteniendo TMS:', e.message);
}

// Excel del ED — buscar en el nodo Fetch ED Excel
try {
  const edItems = $items('Fetch ED Excel', 0, 0);
  if (edItems && edItems.length > 0 && edItems[0].binary) {
    const binaryKey = Object.keys(edItems[0].binary)[0];
    if (binaryKey) {
      excelB64 = edItems[0].binary[binaryKey].data || null;
    }
  }
} catch(e) {
  console.log('ED no disponible, continuando sin Excel:', e.message);
}

return {
  json: {
    csv: csvData,
    excel: excelB64,
    config: {
      site: 'CIU',
      proyectado: 239000,
      objetivoHU: 75,
      productividadHU: 180,
      horaInicioHU: 10,
      horaInicioBipeos: 9,
      horaInicioArribos: 9
    }
  }
};

const result = items[0].json;
console.log('Auto-upload resultado:', JSON.stringify(result, null, 2));
return items;
